package com.ds.goroute.controller;
import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.request.UpdateConversationStatusRequest;import com.ds.goroute.dto.response.MarketplaceConversationResponse;import com.ds.goroute.service.MarketplaceChatService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.authentication.AuthenticationCredentialsNotFoundException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/v1/api/partner/conversations") @RequiredArgsConstructor
public class PartnerMarketplaceChatController {private final MarketplaceChatService s;@GetMapping public ResponseEntity<BaseResponse<List<MarketplaceConversationResponse>>> list(Authentication a,@RequestParam UUID organizationId,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerList(user(a),organizationId,status,page,size)));}@PatchMapping("/{id}")public ResponseEntity<BaseResponse<MarketplaceConversationResponse>> update(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpdateConversationStatusRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerUpdate(user(a),id,r)));}private UUID user(Authentication a){if(a==null||a.getPrincipal()==null)throw new AuthenticationCredentialsNotFoundException("Authentication required");Object p=a.getPrincipal();return p instanceof UUID id?id:UUID.fromString(p.toString());}}
